<template>
	<Layout>
		<div class="container box_general">
			<div class="header_box">
				<h2><i class="icon-medicine"></i>Prescripciones</h2>
			</div>

			<div class="filters-box">
				<div class="filter">
					<label>BUSCAR</label>
					<div class="filter-input">
						<i class="icon icon-search"></i>
						<input type="text" class="form-control" placeholder="Buscar" v-model="filters.search" @keyup.enter="updateFilters($event)" />
						<div
							class="btn btn-light btn-clear-filter"
							v-if="filters.search"
							@click="
								filters.search = null
								updateFilters()
							"
						>
							<i class="icon icon-close"></i>
						</div>
					</div>
				</div>
			</div>

			<table class="table table-clickeable">
				<tr class="table-head">
					<td>Código</td>
					<td>Paciente</td>
					<td>Medicamento</td>
					<td class="d-flex">Vencimiento <i class="fa fa-question-circle text-secondary p-1" v-b-tooltip.hover :title="`Fecha límite para dispensar`"></i></td>
				</tr>

				<router-link tag="tr" :to="`/prescriptions/${item.id}`" v-for="item of list" :key="item.id">
					<td>
						<div class="tc">
							<span>{{ item.code }}</span>
							<span class="text-secondary">{{ item.createdAt | moment("DD-MM-YYYY") }}</span>
						</div>
					</td>
					<td>
						<div class="tc">
							<span>{{ item.patient.name }} {{ item.patient.lastname }}</span>
							<span class="text-secondary" v-if="item.patient.document">{{ item.patient.document.type }} {{ item.patient.document.number }}</span>
						</div>
					</td>
					<td>
						<div class="tc">
							<span>{{ item.product.name }}</span>
							<span class="text-secondary" v-if="item.product.presentation">{{ item.product.presentation }}</span>
						</div>
					</td>
					<td>
						<div class="tc">
							<span>{{ item.expireAt | moment("DD-MM-YYYY") }}</span>
						</div>
					</td>
					<td>
						<div class="tc">
							<span class="d-flex" v-b-tooltip.hover :title="item.statusHelp">
								<i class="dot mt-1 mr-1" :class="`dot-${item.statusClass}`"></i>
								<span>{{ item.statusText }}</span>
							</span>
							<span v-if="item.dispensation">{{ item.dispensation.createdAt | moment("DD-MM-YYYY HH:mm") }}</span>
						</div>
					</td>
				</router-link>
			</table>

			<div class="alert alert-info text-center" v-if="list.length == 0">No se han encontrado prescripciones</div>

			<Pagination :pageData="pagination" @pageChange="pageChange" />
		</div>
	</Layout>
</template>

<script>
import gql from "graphql-tag"

export default {
	name: "Prescriptions",

	data() {
		return {
			list: [],
			loading: true
		}
	},
	beforeMount() {
		this.filters = this.getValidUrlParams()
		this.load()
	},

	methods: {
		load() {
			this.loading = true
			this.$apollo
				.query({
					query: gql`
						query($take: Int, $skip: Int, $search: String) {
							prescriptions(take: $take, skip: $skip, search: $search) {
								data {
									id
									code
									patient {
										id
										name
										lastname
										document {
											type
											number
										}
									}
									dispensation {
										id
										createdAt
									}
									product {
										id
										name
										presentation
									}
									expireAt
									createdAt
									statusClass
									statusText
									statusHelp
								}
								pageInfo {
									totalItems
								}
							}
						}
					`,
					variables: {
						take: this.pagination.length,
						skip: this.pagination.skip,
						search: this.filters.search
					},
					fetchPolicy: "no-cache"
				})
				.then(data => {
					this.list = data.data.prescriptions.data.map(item => {
						return { ...item, loading: false }
					})
					this.pagination.pageInfo = data.data.prescriptions.pageInfo
					this.loading = false
				})
		}
	}
}
</script>

